#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Polar setup for CMO plans and Project top-ups (SOKD-204, ADR 0068).
#
#   bash apps/core/scripts/polar-setup.sh sandbox
#   bash apps/core/scripts/polar-setup.sh production
#
# One run per Polar environment; the two never share a value. A sandbox run
# writes apps/core/.env and the sandbox Vercel targets. A production run writes
# only sokosumi-core-mainnet Production and keeps nothing on this machine.
# No secret is printed: secrets are typed hidden and reach Vercel on stdin.

# ══ CONTRACT WITH CORE ═════════════════════════════════════════════════════
# The one place that must match Core's Polar client module
# (src/clients/polar.client.ts), env schema (src/config/env.ts), webhook route
# (src/routes/v1/webhooks/polar.ts) and catalog
# (src/services/cmo-catalog.service.ts). Change names here, nowhere else.

ENV_TOKEN="POLAR_ACCESS_TOKEN"
ENV_SECRET="POLAR_WEBHOOK_SECRET"
ENV_ENVIRONMENT="POLAR_ENVIRONMENT" # value: sandbox | production

WEBHOOK_PATH="/v1/webhooks/polar"

# Product metadata keys, as Core's catalog reads them: kind is "plan" or
# "top-up", credits a positive whole number, tier any slug and on plans only.
META_KIND="kind"
META_TIER="tier"
META_CREDITS="credits"

# The dated API version Core's client imports (@polar-sh/sdk/2026-10). The
# webhook endpoint must send payloads of this version.
API_VERSION="2026-10"

# name | price in USD | billing cycle | kind | tier slug (plans only) | credits
# Plan credits are the monthly amount, on yearly products too.
CATALOG=(
  "CMO Starter (monthly)|200|Monthly|plan|starter|10000"
  "CMO Growth (monthly)|500|Monthly|plan|growth|25000"
  "CMO Scale (monthly)|1,000|Monthly|plan|scale|50000"
  "CMO Starter (yearly)|2,000|Yearly|plan|starter|10000"
  "CMO Growth (yearly)|5,000|Yearly|plan|growth|25000"
  "CMO Scale (yearly)|10,000|Yearly|plan|scale|50000"
  "CMO top-up 5,000 credits|150|One-time|top-up||5000"
  "CMO top-up 10,000 credits|300|One-time|top-up||10000"
  "CMO top-up 25,000 credits|750|One-time|top-up||25000"
)

# Scopes Core's calls need: checkouts, customer sessions (portal link),
# subscriptions (read, change plan, revoke), products (catalog), orders.
TOKEN_SCOPES=(
  "checkouts:write"
  "customer_sessions:write"
  "subscriptions:read"
  "subscriptions:write"
  "products:read"
  "orders:read"
)

# Events Core's webhook route handles; any other type is answered 202.
WEBHOOK_EVENTS=(
  "order.paid"
  "order.refunded"
  "subscription.created"
  "subscription.active"
  "subscription.updated"
  "subscription.canceled"
  "subscription.uncanceled"
  "subscription.past_due"
  "subscription.revoked"
)

# Core's catalog reader: a module path relative to apps/core and its export,
# an async function without arguments that returns { plans, topUps }. An entry
# carries productId, name, credits, priceAmount (in cents) and currency; a plan
# also tier and interval ("month" | "year").
CATALOG_MODULE="./src/services/cmo-catalog.service.ts"
CATALOG_EXPORT="getCmoCatalog"

# read_catalog TOKEN SECRET ENVIRONMENT prints one line per catalog entry as
# Core reads it from Polar, and fails unless there are nine. The three values
# override apps/core/.env for this one process (Node keeps a variable that is
# already set over --env-file), so a production check leaves no file behind.
read_catalog() {
  (
    cd apps/core
    export "$ENV_TOKEN=$1" "$ENV_SECRET=$2" "$ENV_ENVIRONMENT=$3"
    export CATALOG_MODULE CATALOG_EXPORT
    pnpm exec tsx --env-file=.env -e '
      import(process.env.CATALOG_MODULE)
        .then(async (module) => {
          const catalog = await module[process.env.CATALOG_EXPORT]();
          const entries = [...catalog.plans, ...catalog.topUps];
          for (const entry of entries) console.log(JSON.stringify(entry));
          console.log(`${entries.length} of 9 entries`);
          process.exit(entries.length === 9 ? 0 : 1);
        })
        .catch((error) => {
          console.error(String(error?.message ?? error));
          process.exit(1);
        });
    '
  )
}
# ══ END OF CONTRACT ════════════════════════════════════════════════════════

VERCEL_SCOPE="masumi"

# vercel_env NAME VALUE PROJECT TARGET TYPE-FLAG sets one variable on a Vercel
# project. The value goes in on stdin and the CLI's output is dropped.
vercel_env() {
  local name="$1" value="$2" project="$3" target="$4" type_flag="$5"
  if printf '%s' "$value" | vercel env add "$name" --environment "$target" \
    --project "$project" --scope "$VERCEL_SCOPE" "$type_flag" --force --yes \
    >/dev/null 2>&1; then
    printf '  %s✓ set%s %s on %s (%s)\n' "$GREEN" "$RESET" "$name" "$project" "$target"
  else
    SKIPPED+=("$name on $project ($target): vercel env add $name --environment $target --project $project --scope $VERCEL_SCOPE --force")
    warn "could not set $name on $project ($target)"
  fi
}

# product_stage "Title" CYCLE walks through the three products of one billing cycle.
product_stage() {
  local title="$1" cycle="$2" row name price row_cycle kind tier credits metadata count=0
  stage "$title"
  say "Create three products. Type every metadata value exactly:"
  say "Core ignores a product whose metadata it cannot read."
  open_url "$DASHBOARD/products/new"
  note "Products → New Product. Labels in Polar's form may differ slightly."
  for row in "${CATALOG[@]}"; do
    IFS='|' read -r name price row_cycle kind tier credits <<<"$row"
    [[ "$row_cycle" == "$cycle" ]] || continue
    count=$((count + 1))
    printf '\n'
    step "Product $count of 3: $BOLD$name$RESET"
    say "    Billing cycle: $row_cycle (cannot be changed later)"
    say "    Pricing: Fixed price, \$$price USD. No trial, no benefits."
    metadata="$META_KIND = $kind"
    [[ -n "$tier" ]] && metadata+="    $META_TIER = $tier"
    say "    Metadata: $metadata    $META_CREDITS = $credits"
    pause "Saved? Press Enter for the next one"
  done
}

run_wizard() {

local polar_env="${1:-}" default_core_url core_url token secret output catalog_ok=1
local row project target name price row_cycle kind tier credits
local -a vercel_targets

case "$polar_env" in
  sandbox)
    POLAR_SITE="https://sandbox.polar.sh"
    default_core_url="https://api.preprod.sokosumi.com"
    vercel_targets=(
      "sokosumi-core-preprod production"
      "sokosumi-core-preprod preview"
      "sokosumi-core-mainnet preview"
    )
    ;;
  production)
    POLAR_SITE="https://polar.sh"
    default_core_url="https://api.sokosumi.com"
    vercel_targets=("sokosumi-core-mainnet production")
    ;;
  *)
    printf 'Usage: %s sandbox|production\n' "$0" >&2
    return 2
    ;;
esac

cd "$(dirname "${BASH_SOURCE[0]}")/../../.."

# Production values never touch a local file: nothing to remember, nothing to write.
if [[ "$polar_env" == sandbox ]]; then ENV_FILE="apps/core/.env"; else ENV_FILE="/dev/null"; fi

if [[ "$(_existing "$ENV_ENVIRONMENT" || true)" == production ]]; then
  printf '%s holds production Polar values. Remove its %s, %s and %s lines, then run again.\n' \
    "$ENV_FILE" "$ENV_TOKEN" "$ENV_SECRET" "$ENV_ENVIRONMENT" >&2
  return 1
fi

TOTAL_STAGES=10

banner "Polar setup for CMO: $polar_env"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Polar: sign in to the $polar_env organization"
if [[ "$polar_env" == sandbox ]]; then
  say "Sandbox is a separate Polar site with its own account, organization and tokens."
  open_url "$POLAR_SITE/start"
  step "Sign in, or create the sandbox account and an organization for Sokosumi CMO."
else
  warn "This run configures the LIVE Polar organization. It will sell to real cards."
  confirm "Continue with production?" || return 1
  open_url "$POLAR_SITE/dashboard"
  step "Sign in and switch to the organization that sells CMO."
fi
step "Look at the address bar: $POLAR_SITE/dashboard/<slug>/..."
POLAR_ORG_SLUG=""
while [[ -z "$POLAR_ORG_SLUG" ]]; do ask POLAR_ORG_SLUG "Organization slug:"; done
DASHBOARD="$POLAR_SITE/dashboard/$POLAR_ORG_SLUG"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Polar: allow multiple subscriptions"
say "The organization is the Polar customer and each Cuso has his own subscription,"
say "so one customer must be able to hold several at once."
open_url "$DASHBOARD/settings"
step "Settings → Subscriptions (the organization's general settings)."
step "Switch ON \"Allow multiple subscriptions\". Save."
note "In Polar's API this is subscription_settings.allow_multiple_subscriptions."
pause "Multiple subscriptions are on? Press Enter"

# ── 3 to 5 ────────────────────────────────────────────────────────────────
product_stage "Polar: three monthly CMO plans" "Monthly"
product_stage "Polar: three yearly CMO plans" "Yearly"
product_stage "Polar: three Project top-up packs" "One-time"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Polar: access token"
open_url "$DASHBOARD/settings"
step "Settings → Access Tokens (older layout: Settings → Developers) → Create token."
step "Name it \"Sokosumi Core ($polar_env)\". Pick an expiry and put it in the team calendar."
step "Tick exactly these scopes:"
for row in "${TOKEN_SCOPES[@]}"; do say "      $row"; done
step "Create it and copy the token. Polar shows it once."
while [[ -z "${!ENV_TOKEN:-}" ]]; do ask_secret "$ENV_TOKEN" "Paste the access token (hidden):"; done
token="${!ENV_TOKEN}"
if [[ "$token" != polar_oat_* ]]; then
  warn "That does not start with polar_oat_, as organization access tokens do."
  confirm "Use it anyway?" || return 1
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Polar: webhook endpoint"
say "Polar sends its events to Core. Which Core does this $polar_env organization reach?"
core_url=""
ask core_url "Core base URL [Enter for $default_core_url]:"
core_url="${core_url:-$default_core_url}"
core_url="${core_url%/}"
open_url "$DASHBOARD/settings/webhooks"
step "Settings → Webhooks → Add Endpoint."
step "URL:    $core_url$WEBHOOK_PATH"
step "Format: Raw"
step "API version (payload version): $API_VERSION. Core reads no other version."
step "Secret: generate a random one and copy it."
step "Events: tick exactly these."
for row in "${WEBHOOK_EVENTS[@]}"; do say "      $row"; done
step "Save the endpoint."
if [[ "$polar_env" == sandbox ]]; then
  note "Every sandbox Core (preprod, PR previews, local) reads the same secret. When you"
  note "add an endpoint for a preview or a tunnel later, give it this same secret."
fi
while [[ -z "${!ENV_SECRET:-}" ]]; do ask_secret "$ENV_SECRET" "Paste the webhook secret (hidden):"; done
secret="${!ENV_SECRET}"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Polar: customer portal"
say "Owners and admins cancel and pay in Polar's portal, but change plan in CMO,"
say "because the portal cannot keep a change within monthly or yearly."
open_url "$DASHBOARD/settings"
step "Settings → Customer Portal."
step "Switch OFF the toggle that lets customers change their subscription plan."
step "Leave cancelling and payment method changes ON. Save."
pause "Plan changes are off? Press Enter"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Write the values where Core reads them"
if [[ "$polar_env" == sandbox ]]; then
  write_env "$ENV_TOKEN" "$token"
  write_env "$ENV_SECRET" "$secret"
  write_env "$ENV_ENVIRONMENT" "$polar_env"
else
  note "Production values are not written to this machine."
fi
say "Vercel targets for $polar_env (team $VERCEL_SCOPE), overwriting what is there:"
for row in "${vercel_targets[@]}"; do say "      $row"; done
if ! command -v vercel >/dev/null 2>&1 || ! vercel whoami --scope "$VERCEL_SCOPE" >/dev/null 2>&1; then
  warn "The Vercel CLI is missing or not signed in (pnpm add -g vercel; vercel login)."
  for row in "${vercel_targets[@]}"; do SKIPPED+=("$ENV_TOKEN, $ENV_SECRET, $ENV_ENVIRONMENT on $row"); done
elif confirm "Set the three variables on these targets now?"; then
  for row in "${vercel_targets[@]}"; do
    read -r project target <<<"$row"
    vercel_env "$ENV_TOKEN" "$token" "$project" "$target" --sensitive
    vercel_env "$ENV_SECRET" "$secret" "$project" "$target" --sensitive
    vercel_env "$ENV_ENVIRONMENT" "$polar_env" "$project" "$target" --no-sensitive
  done
  note "Running deployments keep their old values until the next deploy."
else
  for row in "${vercel_targets[@]}"; do SKIPPED+=("$ENV_TOKEN, $ENV_SECRET, $ENV_ENVIRONMENT on $row"); done
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Check: Core reads the catalog from Polar"
say "Expected, nine entries:"
for row in "${CATALOG[@]}"; do
  IFS='|' read -r name price row_cycle kind tier credits <<<"$row"
  say "      $kind  ${tier:--}  $row_cycle  $credits credits  \$$price"
done
printf '\n'
say "Core reads:"
if [[ ! -f apps/core/.env ]]; then
  catalog_ok=0
  warn "apps/core/.env is missing, so Core cannot start here. Run: pnpm env:bootstrap"
else
  output=$(read_catalog "$token" "$secret" "$polar_env" 2>&1) || catalog_ok=0
  output="${output//"$token"/[token]}"
  output="${output//"$secret"/[secret]}"
  printf '%s\n' "$output" | while IFS= read -r row; do say "      $row"; done
fi
if (( catalog_ok )); then
  printf '  %s✓ nine entries%s Compare tier, credits and price (priceAmount is in cents) with the list above.\n' "$GREEN" "$RESET"
else
  warn "Core did not read nine entries. Fix the product's metadata in Polar, then run again."
  warn "If the module was not found, align the CONTRACT block with Core."
  SKIPPED+=("catalog check: Core did not read nine products with valid metadata")
fi
pause

finish
(( catalog_ok ))
}

run_wizard "$@"; exit
